  pixelsPerSecond: 80, // Default zoom\n    minPPS: 10,\n    maxPPS: 200,\n    trackHeight: 70,\n    snapThresholdPx: 15,\n    screenWidth: window.innerWidth || 360\n  },\n\n  // Principle 1: Time \u003c-\u003e Pixel Conversion\n  timeToPixel(time, scrollOffset) {\n    return (time - scrollOffset) * this.config.pixelsPerSecond;\n  },\n\n  pixelToTime(pixelX, scrollOffset) {\n    return (pixelX / this.config.pixelsPerSecond) + scrollOffset;\n  },\n\n  durationToWidth(duration) {\n    return duration * this.config.pixelsPerSecond;\n  },\n\n  widthToDuration(width) {\n    return width / this.config.pixelsPerSecond;\n  },\n\n  // Principle 2: Playhead Fixed Center Logic (CapCut Style)\n  getScrollOffsetForTime(currentTime) {\n    const centerPixels = this.config.screenWidth / 2;\n    return currentTime - (centerPixels / this.config.pixelsPerSecond);\n  },\n\n  getCurrentTimeFromScroll(scrollOffset) {\n    const centerPixels = this.config.screenWidth / 2;\n    return scrollOffset + (centerPixels / this.config.pixelsPerSecond);\n  },\n\n  // Principle 3: Trim Math - Never cut file, only change sourceOffset\n  calculateTrim(oldClip, dragPixels, side) {\n    // side: 'left' or 'right'\n    const deltaTime = dragPixels / this.config.pixelsPerSecond;\n    let newClip = { ...oldClip };\n\n    if (side === 'left') {\n      // Drag left handle to right = trim start\n      newClip.startTime = oldClip.startTime + deltaTime;\n      newClip.duration = oldClip.duration - deltaTime;\n      newClip.sourceOffset = (oldClip.sourceOffset || 0) + deltaTime;\n      \n      // Prevent negative duration\n      if (newClip.duration \u003c 0.1) {\n        newClip.duration = 0.1;\n        newClip.startTime = oldClip.startTime + oldClip.duration - 0.1;\n        newClip.sourceOffset = oldClip.sourceOffset + oldClip.duration - 0.1;\n      }\n    } else {\n      // Right handle\n      newClip.duration = oldClip.duration + deltaTime;\n      if (newClip.duration \u003c 0.1) newClip.duration = 0.1;\n    }\n    return newClip;\n  },\n\n  // Principle 4: Track Switching via Y\n  getTrackIndexFromY(dragY) {\n    return Math.floor(dragY / this.config.trackHeight);\n  },\n\n  getYFromTrackIndex(trackIndex) {\n    return trackIndex * this.config.trackHeight;\n  },\n\n  // Track Order Locked: V1=0, A1=1, A2=2, V2=3, V3=4, Text=5, Adjustment=6\n  TRACKS: {\n    V1: 0,\n    A1: 1,\n    A2: 2,\n    V2: 3,\n    V3: 4,\n    TEXT: 5,\n    ADJUSTMENT: 6\n  },\n\n  // Principle 5: Smart Snap\n  shouldSnap(clip1End, clip2Start) {\n    const thresholdTime = this.config.snapThresholdPx / this.config.pixelsPerSecond;\n    return Math.abs(clip1End - clip2Start) \u003c thresholdTime;\n  },\n\n  findSnapTarget(currentClip, allClips, playheadTime) {\n    const thresholdTime = this.config.snapThresholdPx / this.config.pixelsPerSecond;\n    let snapTime = null;\n\n    // Snap to other clip edges\n    for (let clip of allClips) {\n      if (clip.id === currentClip.id) continue;\n      if (Math.abs(currentClip.startTime - clip.endTime) \u003c thresholdTime) {\n        snapTime = clip.endTime;\n      }\n      if (Math.abs(currentClip.endTime - clip.startTime) \u003c thresholdTime) {\n        snapTime = clip.startTime - currentClip.duration;\n      }\n    }\n\n    // Snap to playhead\n    if (Math.abs(currentClip.startTime - playheadTime) \u003c thresholdTime) {\n      snapTime = playheadTime;\n    }\n\n    return snapTime;\n  },\n\n  // Zoom\n  setZoom(newPPS) {\n    this.config.pixelsPerSecond = Math.max(this.config.minPPS, Math.min(this.config.maxPPS, newPPS));\n    return this.config.pixelsPerSecond;\n  },\n\n  zoomByFactor(factor) {\n    return this.setZoom(this.config.pixelsPerSecond * factor);\n  },\n\n  // Ripple Edit for V1\n  calculateRipple(allClips, deletedClip) {\n    // Only for V1 track\n    if (deletedClip.track !== this.TRACKS.V1) return allClips;\n    \n    const deletedDuration = deletedClip.duration;\n    return allClips.map(clip =\u003e {\n      if (clip.track === this.T